import React from "react";
import { Link } from "react-router-dom";
import babyImg from "../assets/baby1.jpg"; 

function Home() {
  return (
    <div style={{
      display: "flex",
      alignItems: "center",
      justifyContent: "space-around",
      padding: "80px 20px",
      background: "#fff5f9"
    }}>

      <div>
        <h1 style={{ fontSize: "48px", color: "#d63384" }}>
          Nanhe Farishte <br /> Kiran Knits
        </h1>

        <p style={{ fontSize: "20px", marginTop: "20px" }}>
          Maa ke haathon ki garmahat ❤️
        </p>

        <button style={{
          marginTop: "25px",
          padding: "14px 30px",
          background: "#ff85a2",
          border: "none",
          borderRadius: "25px",
          color: "white"
        }}>
          Shop Now
        </button>
      </div>

      <img 
        src={117} 
        alt="Mother and Baby"
        style={{
          width: "350px",
          borderRadius: "20px",
          boxShadow: "0 20px 50px rgba(0,0,0,0.15)"
        }}
      />

  
      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "34px",
            marginBottom: "60px",
            color: "#444",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform =
            "translateY(-15px) scale(1.05)";
          e.currentTarget.style.background =
            "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform =
            "translateY(0) scale(1)";
          e.currentTarget.style.background = "white";
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
